const registros = $input.all();

const fuentes = registros.map(item => {
  const data = item.json.fields ?? item.json;

  return {
    id: item.json.id ?? data['Record ID'] ?? '',
    tema: data.Tema ?? '',
    categoria: data['Categoría'] ?? '',
    prioridad: data.Prioridad ?? null
  };
});

const contexto = registros
  .map(item => {
    const data = item.json.fields ?? item.json;

    const tema = data.Tema ?? '';
    const contenido = data.Contenido ?? '';

    return `### ${tema}\n${contenido}`;
  })
  .join('\n\n');

return [
  {
    json: {
      contexto_rag: contexto,
      fuentes_rag: fuentes,
      cantidad_fuentes: fuentes.length
    }
  }
];

