={{
  (() => {
    const ids = $('Airtable Trigger').first().json.fields['Contexto relacionado'] || [];

    if (ids.length === 0) {
      return '{Prioridad}=10';
    }

    return 'OR({Prioridad}=10,' +
      ids.map(id => `{Record ID}="${id}"`).join(',') +
      ')';
  })()
}}

