parameters.jsCode:
const input = $input.first().json;

// Respuesta completa de OpenAI Responses API
const output = input.output ?? [];

// Buscar el mensaje del assistant
const mensaje = output.find(item =>
  item.type === 'message' &&
  item.role === 'assistant'
);

// Buscar el bloque de texto
const bloqueTexto = mensaje?.content?.find(
  item => item.type === 'output_text'
);

const raw = bloqueTexto?.text ?? {};

let data;

// Con JSON Schema, OpenAI/n8n puede devolver
// el resultado ya parseado como objeto.
if (raw !== null && typeof raw === 'object') {
  data = raw;
} else {
  try {
    data = JSON.parse(raw);
  } catch (e) {
    data = {
      titulo: '',
      caption: String(raw ?? ''),
      hashtags: [],
      requiere_revision: true
    };
  }
}

const hashtagsTexto = Array.isArray(data.hashtags)
  ? data.hashtags
      .map(h => `#${String(h).replace(/^#/, '')}`)
      .join(' ')
  : '';

const borrador = `${data.titulo ?? ''}

${data.caption ?? ''}

${hashtagsTexto}`.trim();

// Recuperamos los datos originales preparados antes de OpenAI
const origen = $('Preparar Prompt IA').first().json;

return [
  {
    json: {
      record_id: origen.record_id,
      idea_semilla: origen.idea_semilla,

      titulo: data.titulo ?? '',
      caption: data.caption ?? '',
      hashtags: data.hashtags ?? [],
      requiere_revision: data.requiere_revision ?? true,

      borrador_ia: borrador,

      // Trazabilidad técnica
      openai_response_id: input.id ?? '',
      modelo: input.model ?? '',
      tokens_entrada: input.usage?.input_tokens ?? 0,
      tokens_salida: input.usage?.output_tokens ?? 0,
      tokens_totales: input.usage?.total_tokens ?? 0,
      tokens_cacheados:
        input.usage?.input_tokens_details?.cached_tokens ?? 0
    }
  }
];
